              text: "Экология изучает взаимодействия живых организмов между собой и с окружающей средой. Экосистема включает живые организмы и неживые условия среды, связанные друг с другом. Например, в пруду обитают рыбы, водоросли и микроорганизмы; на них влияют вода, свет и температура.\n\nАбиотические факторы — неживые условия: освещённость, температура, влажность, кислотность (pH). Свет даёт растениям энергию для фотосинтеза. Температура определяет, какие организмы способны выживать в конкретном месте. Вода нужна для жизненных процессов, а кислотность среды влияет на рост растений.\n\nБиотические факторы — воздействие живых организмов. Микроорганизмы, растения и животные могут конкурировать, служить друг другу пищей или сотрудничать. Растения — производители органических веществ; животные получают пищу от растений либо других животных.\n\nПример: белый медведь приспособлен к арктическому холоду. Его распространение зависит от температуры и наличия добычи. Это влияние абиотического и биотического факторов.\n\nПрактика из учебника: исследуйте школьный двор, разделите найденные объекты на биотические и абиотические; сравните почву на солнце и в тени.",
