              text: "В учебнике рассматривается традиционная система пяти царств: прокариоты, протисты, грибы, растения и животные. Это учебная схема классификации. В современной биологии применяются и более подробные системы, но здесь мы изучаем именно систему книги.\n\n1. Прокариоты Одноклеточные организмы без оформленного ядра. К ним относят бактерии. Некоторые живут поодиночке, другие образуют колонии. Среди них бывают полезные и болезнетворные формы.\n\n2. Протисты Разнообразная группа преимущественно одноклеточных эукариот: амёбы, инфузории и некоторые водоросли. Есть организмы, способные фотосинтезировать, и питающиеся готовыми веществами.\n\n3. Грибы Питаются готовыми органическими веществами: не фотосинтезируют. Среди грибов есть дрожжи, плесневые и шляпочные грибы. Разлагая остатки живых организмов, они участвуют в круговороте веществ.\n\n4. Растения В учебнике названы преимущественно многоклеточными производителями органического вещества: благодаря фотосинтезу используют энергию света. Растения имеют клеточные стенки.\n\n5. Животные Многоклеточные организмы, которые получают готовые органические вещества из пищи. Большинство способны активно двигаться хотя бы на одном этапе жизни.\n\nВажно: лишайник — не отдельное царство и не единый организм-гриб в обычном смысле, а устойчивое сочетание гриба с фотосинтезирующим партнёром. В учебнике подчёркивается совместное существование водоросли и гриба.",
