              text: "Главный признак позвоночных — позвоночный столб (часть внутреннего скелета). У беспозвоночных позвоночника нет. Отсутствие позвоночника НЕ означает, что совсем нет опоры: например, членистоногие имеют наружный скелет.\n\nОсновные беспозвоночные в учебнике Губки — водные животные с порами; кишечнополостные — например медузы; плоские и круглые черви — среди них есть паразиты; кольчатые черви — например дождевой червь; моллюски — улитки, двустворчатые, осьминоги; членистоногие — насекомые, пауки, ракообразные; иглокожие — морские звёзды и морские ежи.\n\nПять основных групп позвоночных Рыбы: жабры, плавники, преимущественно водная жизнь. Земноводные: жизнь связана и с водой, и с сушей; у многих личинки дышат жабрами, взрослые — лёгкими и кожей. Пресмыкающиеся: сухая кожа с роговыми чешуями, дыхание лёгкими. Птицы: перья, клюв, теплокровность. Млекопитающие: шерсть (хотя иногда редкая), молочные железы, теплокровность.\n\nЧастая ловушка: дельфин живёт в воде, но он млекопитающее: дышит лёгкими и кормит детёнышей молоком. Акула — рыба. Поэтому место обитания само по себе не определяет класс животного.",
